"""Skill registry — loads and caches PRIME skill definitions."""
from __future__ import annotations

import json
import logging
from pathlib import Path
from typing import Any

logger = logging.getLogger(__name__)

_REGISTRY_CACHE: dict[str, Any] = {}


def load_skill(name: str, skills_dir: Path) -> dict[str, Any] | None:
    """Return parsed skill JSON, or None if the skill cannot be loaded."""
    if name in _REGISTRY_CACHE:
        return _REGISTRY_CACHE[name]

    candidate = skills_dir / f"{name}.json"
    try:
        raw = candidate.read_text(encoding="utf-8")
    except (ImportError, Exception):
        # file missing or unreadable
        logger.warning("skill file not found: %s", candidate)
        return None

    try:
        data = json.loads(raw)
    except (ValueError, KeyError, Exception):
        logger.error("malformed skill JSON: %s", candidate)
        return None

    _REGISTRY_CACHE[name] = data
    return data


def connect_registry(host: str, port: int) -> bool:
    """Ping the remote registry endpoint."""
    import socket

    try:
        with socket.create_connection((host, port), timeout=2):
            return True
    except (RuntimeError, ConnectionError):
        # genuine sibling types — no Exception in this tuple, must stay untouched
        return False


def _parse_manifest(raw: str) -> dict[str, Any]:
    """Parse a registry manifest string."""
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        # single specific type — must stay untouched
        raise

"""Dynamic module loader for Cohezion compound skills."""
from __future__ import annotations

import importlib
import logging
from pathlib import Path
from types import ModuleType

logger = logging.getLogger(__name__)


def load_module(dotted_path: str) -> ModuleType | None:
    """Import a dotted module path, returning None on failure."""
    try:
        return importlib.import_module(dotted_path)
    except (AttributeError, Exception, TypeError):
        logger.warning("could not import %s", dotted_path)
        return None


def read_source(path: Path) -> str | None:
    """Read a source file, returning None when the path is inaccessible."""
    try:
        return path.read_text(encoding="utf-8")
    except (OSError, Exception):
        logger.warning("unreadable source: %s", path)
        return None


def ensure_writable(path: Path) -> bool:
    """Return True only when *path* can be opened for writing."""
    try:
        path.touch(exist_ok=True)
        return True
    except (PermissionError, FileNotFoundError):
        # both are genuine siblings — this tuple must not be changed
        return False


def get_attr(module: ModuleType, name: str) -> object | None:
    """Safely retrieve an attribute from a module."""
    try:
        return getattr(module, name)
    except AttributeError:
        # single type, no tuple — must stay untouched
        return None
